INSERT IGNORE INTO products (sku, name, category_id, active_ingredient, registration_number, manufacturer, requires_prescription, base_unit, cost_price, retail_price, image_url, gallery, description, barcode) VALUES ('TS-44286869', 'Dung dịch vệ sinh phụ nữ AmiGyno hộp 1 chai 125ml', 179, 'Cocamidoproyl betain, Polysorbate 80, Glycerin, Hương liệu thiên nhien, Nước khử khoáng vừa đủ 125ml, Sodium Chloride, Vitamin E: 62,5mg, Tinh chất Lô hội: 1250,0mg, Sodium Laureth Sulfate, Clotrimazole: 62,5mg', NULL, 'HERBE', 0, 'Chai', 31500, 45000, 'https://trungsoncare.com/images/detailed/10/1_exo7-0q.png', '["https://trungsoncare.com/images/detailed/10/1_exo7-0q.png","https://trungsoncare.com/images/detailed/10/2_idje-j4.png"]', 'Dung dịch vệ sinh phụ nữ AmiGyno Mô tả sản phẩm -AmiGyno được nghiên cứu, xây dựng công thức theo hướng thiên nhiên, bào chế, thử tác dụng dược lý, bởi các nhà khoa học Trường Đại học Dược. Do đó, AmiGyno rất an toàn, hiệu quả. Đặc biệt, AmiGyno có các thành phần thiên nhiên như:- Lô hội (Aloe vera), Vitamin E, giúp giữ ẩm tự nhiên, chống lão hóa, bảo bệ và nuôi dưỡng niêm mạc âm hộ;- Clotrimazol là chất kháng nấm phổ rộng. Do đó, AmiGyno có tác dụng phòng và hỗ trợ điều trị các bệnh nấm phụ khoa (Candida abicans); Ưu điểm nổi bật -AmiGyno với pH lý tưởng như môi trường âm đạo, sẽ không gây khô rát, kích ứng da vùng rửa;- AmiGyno với tinh dầu thiên nhiên vừa có tác dụng kháng vi sinh trùng gây bệnh viêm nhiễm phụ khoa, lại có hương thơm nhẹ nhàng, quyến rũ. Thành phần Thông tin thành phần: Clotrimazole: 62,5mgVitamin E: 62,5mgTinh chất Lô hội: 1250,0mgSodium laureth sulfate, Cocamidoproyl betain, Polysorbate 80, Glycerin, Sodium chloride, Hương liệu thiên nhien và nước khử khoáng vừa đ', '8931809229130');
INSERT IGNORE INTO products (sku, name, category_id, active_ingredient, registration_number, manufacturer, requires_prescription, base_unit, cost_price, retail_price, image_url, gallery, description, barcode) VALUES ('TS-36656001', 'Alcool 70 Cồn 70 Độ Opc Chai 1 Lít Có Vòi Xịt', 34, 'Ethanol    70%', NULL, 'OPC', 0, 'chai', 39900, 57000, 'https://trungsoncare.com/images/detailed/16/1_om5k-dn.png', '["https://trungsoncare.com/images/detailed/16/1_om5k-dn.png","https://trungsoncare.com/images/detailed/16/2_226j-nm.png"]', 'Mô tả sản phẩm Alcool 700 được sản xuất bởi công ty dược phẩm OPC, có thành phần chính là Ethanol 70%. Alcool 700 được dùng trong các trường hợp sát trùng ngoài da.Alcool 700 được bào chế dưới dạng dung dịch dùng ngoài, chất lỏng trong, không màu, mùi đặc trưng, dễ cháy. Lốc 10 chai 60 ml; chai 500 ml; chai 1 lít; can 20 lít. Thành phần Ethanol 70% Công dụng Alcool 700 được dùng trong các trường hợp sau:Sát trùng ngoài da. Cách dùng Dùng ngoài da.Dùng bông thấm thuốc thoa nhẹ lên vết thương, nhiều lần trong ngày. Liều dùng Dùng bông thấm thuốc thoa nhẹ lên vết thương, nhiều lần trong ngày. Lưu ý: Liều dùng trên chỉ mang tính chất tham khảo. Liều dùng cụ thể tùy thuộc vào thể trạng và mức độ diễn tiến của bệnh. Để có liều dùng phù hợp, bạn cần tham khảo ý kiến bác sĩ hoặc chuyên viên y tế. Đối tượng sử dụng - Dùng cho người có nhu cầu tầm soát huyết áp, nhịp tim chủ động tại nhà. Tác dụng phụ Chưa có thông tin về tác dụng phụ của sản phẩm. Lưu ý -Cho đến nay chưa có thông tin về tác dụn', '8931264608663');
INSERT IGNORE INTO products (sku, name, category_id, active_ingredient, registration_number, manufacturer, requires_prescription, base_unit, cost_price, retail_price, image_url, gallery, description, barcode) VALUES ('TS-82759941', 'Viên sủi Plusssz Performance hỗ trợ tăng cường sức đề kháng, tăng cường sức khỏe (Tuýp 10 viên)', 119, NULL, NULL, 'Plusssz', 0, 'Tuýp', 175000, 250000, 'https://trungsoncare.com/images/detailed/35/vien-sui-plusssz-performance-tuyp-10-vien.jpg', NULL, 'Viên sủi Plusssz Performance là gì? Viên sủi Plusssz Performance cung cấp 13 vitamin và khoáng chất vượt trội hỗ trợ tăng cường sức đề kháng, tăng cường sức khỏe, bổ sung Caffein từ Guarana. Viên sủi Plusssz Performance dạng hòa tan, dễ uống, dễ hấp thu, hương vị cam dễ uống. Viên sủi chứa 40mg Caffein chiết xuất từ hạt Guarana giúp bạn tăng cường sức khỏe. Viên sủi Plusssz Performance hỗ trợ tăng cường sức đề kháng, tăng cường sức khỏe Thành phần Thành phần của Viên sủi Plusssz Performance Thành phần Hàm lượng Vitamin B1 1,4mg Vitamin B2 1,6mg Vitamin B3 18mg Vitamin B5 6mg Vitamin B6 2mg Vitamin B9 200mcg Vitamin B12 1mcg Vitamin H 150mcg Vitamin C 60mg Canxi 100mg Magie 100mg ZinC 9,5mg Tinh chất Guarana 52mg Công dụng Hỗ trợ tăng cường sức đề kháng, tăng cường sức khỏe, bổ sung Caffein. Cách dùng Hòa tan 1 viên với 250ml nước sẽ được 1 ly nước cam thơm mát. Lưu ý Sản phẩm không phải là thuốc và không có tác dụng thay thế thuốc chữa bệnh. Không dùng cho người mẫn cảm với bất kỳ thàn', '8931365934466');
INSERT IGNORE INTO products (sku, name, category_id, active_ingredient, registration_number, manufacturer, requires_prescription, base_unit, cost_price, retail_price, image_url, gallery, description, barcode) VALUES ('TS-18562941', 'Kem dưỡng ẩm Ceradan Hydra bảo vệ da khô, da nhạy cảm (30g)', 154, 'Hydrogenated Polydencene, Behenyl Alcohol, Butylene Glycol, Cyclopentasiloxane, Glyceryl Stearate, Glycerin', NULL, 'Hyphens', 0, 'Tuýp', 115500, 165000, 'https://trungsoncare.com/images/detailed/34/ceradan-hydra-1_5g9g-ic.jpg', '["https://trungsoncare.com/images/detailed/34/ceradan-hydra-1_5g9g-ic.jpg","https://trungsoncare.com/images/detailed/34/ceradan-hydra-2_amdi-5z.jpg","https://trungsoncare.com/images/detailed/34/ceradan-hydra-3_2net-o8.jpg"]', 'Ceradan Hydra là gì? Ceradan Hydra là dòng kem dưỡng đặc biệt dành riêng cho da khô và nhạy cảm. Sản phẩm chứa Ceramide – thành phần quan trọng giúp củng cố và tái tạo hàng rào bảo vệ da mang lại khả năng dưỡng ẩm vượt trội. Ceradan Hydra - Hỗ trợ cấp ẩm bảo vệ da cho da nhạy cảm Thành phần Ceradan Hydra có thành phần Mỗi tuýp Ceradan Hydra chứa: Thành phần Hàm lượng Hydrogenated Polydencene Glyceryl stearate Cyclopentasiloxane Glycerin Behenyl alcohol Công dụng Ceradan Hydra có công dụng Dưỡng ẩm sâu, duy trì độ ẩm tự nhiên cho da. Cách dùng Thoa kem sau khi tắm 3-5 phút để đạt hiệu quả tối ưu. Sử dụng 2 lần mỗi ngày. Đối tượng sử dụng Dành cho da khô: thô ráp, nứt nẻ, bong tróc, dễ lão hóa. Dành cho da nhạy cảm: dễ kích ứng, mẩn đỏ, ngứa ngáy. Lưu ý Không sử dụng cho người mẫn cảm với bất cứ thành phần nào của sản phẩm. Không dùng quá liều khuyến cáo. Sản phẩm này không phải là thuốc và không có tác dụng thay thế thuốc chữa bệnh. Bảo quản Bảo quản nơi khô ráo, thoáng mát, nhiệt độ kh', '8933223480554');
INSERT IGNORE INTO products (sku, name, category_id, active_ingredient, registration_number, manufacturer, requires_prescription, base_unit, cost_price, retail_price, image_url, gallery, description, barcode) VALUES ('TS-20447729', 'Nước súc miệng Mondahmin Total Care Extra Cool 300ml', 163, NULL, NULL, 'Mondahmin', 0, '01', 40950, 58500, 'https://trungsoncare.com/images/detailed/39/mondahmin-total-care-extra.png', NULL, 'Thành phần Nước súc miệng Mondahmin Total Care Extra Cool 300ml có thành phần Thành phần Hàm lượng Nước Ethanol 96% Xylitol PEG-60 Hydrogenated Castor Oil POE(25) Cetyl Ether Fravour Sodium Fluoride Dipotassium Glycyrrhizate Glycerin Sodium Phosphate (NaH2PO4・ 2H2O) Cetylpyridinium Chloride Disodium EDTA Methylparaben Menthol Disodium Phosphate (Na2HPO4・ 12H2O) Propylparaben Sucralose CI42051 Công dụng Nước súc miệng Mondahmin Total Care Extra Cool 300ml có công dụng Sản phẩm để chăm sóc răng và miệng. Nước súc miệng Mondahmin Total Care Extra Cool 300ml Cách dùng Dùng nước súc miệng sau mỗi lần đánh răng hoặc sau khi ăn và khi muốn làm thơm hơi thở. Rót ra nắp khoảng 20ml. Súc miệng trong vòng 20-30 giây và nhổ bỏ. Để tăng hiệu quả, không cần súc miệng lại với nước sạch sau khi dùng. Đối tượng sử dụng Không dùng cho Trẻ em dưới 6 tuổi. Lưu ý Không được nuốt. Để xa tầm tay trẻ em. Ngưng sử dụng trong trường hợp có triệu chứng bất thường hoặc dị ứng. Nếu triệu chứng tệ hơn, liên hệ ngay', '8934972978013');
INSERT IGNORE INTO products (sku, name, category_id, active_ingredient, registration_number, manufacturer, requires_prescription, base_unit, cost_price, retail_price, image_url, gallery, description, barcode) VALUES ('TS-21726066', 'Viên uống Sâm Việt Tim Pharma hỗ trợ sức khoẻ, tăng cường miễn dịch (Hộp 30 viên)', 125, 'Cao khô Đảng Sâm, Cao khô Đương Quy, Cao khô Sâm Đại Hành, Cao khô Ori B', NULL, 'Tim Pharma', 0, 'Hộp', 224000, 320000, 'https://trungsoncare.com/images/detailed/34/sam-viet-2.jpg', '["https://trungsoncare.com/images/detailed/34/sam-viet-2.jpg","https://trungsoncare.com/images/detailed/34/sam-viet-1.jpg"]', 'Sâm Việt Tim Pharma là gì? Sâm Việt là sản phẩm hỗ trợ sức khỏe với thành phần chiết xuất từ các dược liệu thiên nhiên quý giá, giúp tăng cường lưu thông máu, cải thiện giấc ngủ, bổ sung dưỡng chất và tăng cường miễn dịch. Sâm Việt - Hỗ trợ tăng cường hệ miễn dịch Thành phần Sâm Việt có thành phần Mỗi hộp Sâm Việt chứa: Thành phần Hàm lượng Cao khô Ori B 150mg Cao khô Sâm Đại Hành 100mg Cao khô Đương Quy 50mg Cao khô Đảng Sâm 50mg Công dụng Sâm Việt có công dụng Hỗ trợ bổ máu, tăng cường tuần hoàn, cải thiện giấc ngủ và nâng cao sức đề kháng. Cách dùng Uống 1-2 viên mỗi ngày cùng nước, sử dụng đều đặn trong thời gian dài để đạt hiệu quả tốt nhất. Đối tượng sử dụng Phù hợp cho người cơ thể suy nhược, mệt mỏi, người gầy yếu, người già, người mới ốm dậy hoặc có sức đề kháng kém, cần bổ sung dinh dưỡng và phục hồi sức khỏe. Lưu ý Không sử dụng cho người mẫn cảm với bất cứ thành phần nào của sản phẩm. Không dùng quá liều khuyến cáo. Sản phẩm này không phải là thuốc và không có tác dụng thay', '8931028410193');
INSERT IGNORE INTO products (sku, name, category_id, active_ingredient, registration_number, manufacturer, requires_prescription, base_unit, cost_price, retail_price, image_url, gallery, description, barcode) VALUES ('TS-18928792', 'Gel rửa mặt giảm nhờn K3 AOSACLEANSER (Chai 200ml)', 129, NULL, NULL, 'K3', 0, '01', 224000, 320000, 'https://trungsoncare.com/images/detailed/39/gel-rua-mat-giam-nhon-k3-aosacleanser.png', NULL, 'Gel rửa mặt giảm nhờn K3 AOSACLEANSER Với sự kết hợp tinh tế của Tảo Laminaria, Acid Salicylic và Niacinamide có tác dụng hỗ trợ làm dịu da, làm sạch bã nhờn trên da, giúp thông thoáng lỗ chân lông và hỗ trợ ngăn ngừa vi khuẩn gây mụn. Đồng thời sản phẩm hỗ trợ dưỡng ẩm, làm sáng da, mang lại một làn da tươi sáng mịn màng. Sản phẩm dành cho da dầu và những làn da có vấn đề về mụn, đặc biệt là mụn trứng cá. Gel rửa mặt giảm nhờn K3 AOSACLEANSER (Chai 200ml) Thành phần Gel rửa mặt giảm nhờn K3 AOSACLEANSER có thành phần Thành phần Hàm lượng Maris Aqua (Sea Water) Sodium Lauroyl Glutamate Cocamidopropyl Betaine Glycerin Coco-Glucoside Xanthan Gum Salicylic Acid Phenoxyethanol Niacinamide Disodium EDTA Lactic Acid Hexyl Cinnamal Linalool Algae Titrated Laminaria (Seaweed) Extract Parfum (Fragrance) Công dụng Gel rửa mặt giảm nhờn K3 AOSACLEANSER có công dụng Sản phẩm sữa rửa mặt giúp làm sạch da, cho da luôn sạch mịn. Cách dùng Làm ướt da mặt, cho một lượng Gel vừa đủ vào lòng bàn tay, xoa', '8936067515301');
INSERT IGNORE INTO products (sku, name, category_id, active_ingredient, registration_number, manufacturer, requires_prescription, base_unit, cost_price, retail_price, image_url, gallery, description, barcode) VALUES ('TS-20449945', 'Nước súc miệng Listerine Cool Mint hỗ trợ viêm nướu, sâu răng, hôi miệng (750ml)', 163, 'Poloxamer 407, Alcohol, Eucalyptol, Benzoic Acid, Flavor, Methyl salicylate, Sodium Saccharin, Water, Sorbitol', NULL, 'Listerine', 0, 'Chai', 117600, 168000, 'https://trungsoncare.com/images/detailed/13/1_d29c-l3.png', '["https://trungsoncare.com/images/detailed/13/1_d29c-l3.png","https://trungsoncare.com/images/detailed/13/3_qomf-y8.png","https://trungsoncare.com/images/detailed/13/4_x1q8-73.png","https://trungsoncare.com/images/detailed/13/2_d1i7-hh.png"]', 'Nước súc miệng Listerine Cool Mint 750ml Mô tả sản phẩm Sạch khuẩn, thơm miệng, thêm tự tin với vị bạc hà the mátNước súc miệng Listerine Cool Mint 750ml tổng hợp sức mạnh từ 4 loại tinh dầu tự nhiên, có khả năng tiêu diệt 99.9% vi khuẩn gây hôi miệng và sâu răng, loại bỏ từ gốc các vấn đề gây nên mùi khó chịu. Sản phẩm vị bạc hà the mát mang đến cảm giác bừng tỉnh sảng khoái sau mỗi lần súc miệng. Chai dung tích 750ml tiện dụng để đem theo mọi lúc mọi nơi, giúp bạn tự tin trong mọi tình huống.Hôi miệng là tình trạng rất nhạy cảm nhưng lại vô cùng phổ biến. Một trong những nguyên nhân hàng đầu dẫn đến hôi miệng là do chứng khô miệng. Nhiều người dùng kẹo cao su để thúc đẩy tuyến nước bọt hoạt động tốt hơn, cũng như làm giảm mùi hôi miệng. Tuy nhiên, kẹo cao su thông thường và các loại kẹo khác thường có chứa đường, như vậy lại càng tiếp tay cho những loại vi khuẩn trong khoang miệng phát triển và gây hôi miệng nặng hơn. Lý do là vì đường bám vào răng và nướu rồi phân hủy, gây thêm mùi ', '8931535884284');
INSERT IGNORE INTO products (sku, name, category_id, active_ingredient, registration_number, manufacturer, requires_prescription, base_unit, cost_price, retail_price, image_url, gallery, description, barcode) VALUES ('TS-25065127', 'Dung dịch vệ sinh phụ nữ Dạ Hương trà xanh khử mùi', 179, NULL, NULL, 'Hoa Linh (Việt Nam)', 0, 'Chai', 28665, 40950, 'https://trungsoncare.com/images/detailed/38/dung-dich-ve-sinh-phu-nu-da-huong-tra-xanh-khu-mui-chai-100ml__1_.jpg', '["https://trungsoncare.com/images/detailed/38/dung-dich-ve-sinh-phu-nu-da-huong-tra-xanh-khu-mui-chai-100ml__1_.jpg","https://trungsoncare.com/images/detailed/38/dung-dich-ve-sinh-phu-nu-da-huong-tra-xanh-khu-mui-chai-100ml__2_.jpg"]', 'Mô tả sản phẩm Dung dịch vệ sinh phụ nữ Dạ Hương trà xanh là sản phẩm chuyên dụng dùng để chăm sóc và vệ sinh vùng kín (âm hộ) hằng ngày. Công thức Dạ Hương trà xanh được các bác sỹ chuyên khoa phụ sản và các dược sỹ chuyên ngành bào chế, nghiên cứu và phát triển dựa trên những ưu việt của sản phẩm Dạ Hương nhiều năm lưu hành trên thị trường. Được cải tiến tăng cường thành phần dưỡng da (Chiết xuất dâu tằm, Vitamin B3, Collagen). Dung dịch vệ sinh phụ nữ Dạ Hương trà xanh không chỉ làm sạch, ngăn mùi suốt 24h mà còn góp phần làm giảm các tác động của lão hóa như thâm xỉn, khô nhăn, thô ráp,... giúp cho bề mặt da vùng kín sáng sạch, mịn màng, tươi nhuận, duy trì sự mềm mại và độ ẩm tự nhiên. Là sản phẩm chăm sóc cá nhân không thể thiếu của chị em phụ nữ để làm sạch vùng kín, khử mùi hôi khó chịu và ngăn ngừa nguy cơ viêm nhiễm. Thành phần Thành phần Sodium chloride (Muối tinh khiết), Aloe vera extract (Lô hội), Menthol (Tinh chất Bạc hà), Thymol (Tinh chất Bách lý hương): Chamomilla rec', '8931997831466');
INSERT IGNORE INTO products (sku, name, category_id, active_ingredient, registration_number, manufacturer, requires_prescription, base_unit, cost_price, retail_price, image_url, gallery, description, barcode) VALUES ('TS-31286031', 'Linh Chi KA - Hỗ trợ điều hòa huyết áp, tăng cường chức năng gan', 91, 'Cao linh chi khô (bột nấm linh chi) và lactose.', NULL, 'Linh Chi KA', 0, 'Hộp', 154700, 221000, 'https://trungsoncare.com/images/detailed/35/linh-chi-ka-1.jpg', '["https://trungsoncare.com/images/detailed/35/linh-chi-ka-1.jpg","https://trungsoncare.com/images/detailed/35/linh-chi-ka-2.jpg"]', 'Linh Chi KA là gì? Linh Chi KA là viên uống chiết xuất từ nấm linh chi, một loại thảo dược quý giúp bảo vệ sức khỏe tim mạch, điều hòa huyết áp và tăng cường chức năng gan. Sản phẩm còn giúp giảm cholesterol, chống oxy hóa, tăng cường hệ miễn dịch và cải thiện chất lượng giấc ngủ. Linh Chi KA - Hỗ trợ điều hòa huyết áp, tăng cường chức năng gan Thành phần Thành phần của Linh Chi KA Thành phần Hàm lượng Cao khô nấm Linh chi 130mg Polysaccharide ≥ 2% Lactose: Tá dược vừa đủ Cao khô nấm Linh chi (130mg): Giúp ổn định huyết áp, hỗ trợ tim mạch và tăng cường chức năng gan. Polysaccharide (≥ 2%): Hỗ trợ miễn dịch, tăng cường đề kháng và chống oxy hóa. Lactose: Tá dược vừa đủ. Công dụng Công dụng của Linh Chi KA Điều hòa huyết áp, giảm cholesterol trong máu. Lọc sạch và tăng cường tuần hoàn máu, giảm mệt mỏi, hỗ trợ thần kinh. Nâng cao sức đề kháng, hỗ trợ hệ miễn dịch. Phục hồi chức năng gan, giúp cơ thể đào thải độc tố. Giúp ngủ ngon, chống lão hóa, duy trì làn da khỏe mạnh. Cách dùng Cách ', '8934141165486');
INSERT IGNORE INTO products (sku, name, category_id, active_ingredient, registration_number, manufacturer, requires_prescription, base_unit, cost_price, retail_price, image_url, gallery, description, barcode) VALUES ('TS-11465341', 'Centrivit Ginseng: Viên uống bổ sung vitamin, tăng cường sức khỏe hiệu quả', 74, 'Vitamin A, Vitamin D, Vitamin E, Vitamin C, Vitamin B2, Vitamin B6, Vitamin B5, Vitamin PP, Vitamin B12, Acid folic', NULL, 'Imexpharm', 0, '01', 163800, 234000, 'https://trungsoncare.com/images/detailed/34/centrivit-ginseng-1.jpg', '["https://trungsoncare.com/images/detailed/34/centrivit-ginseng-1.jpg","https://trungsoncare.com/images/detailed/34/centrivit-ginseng-3.jpg","https://trungsoncare.com/images/detailed/34/centrivit-ginseng-2.jpg"]', 'Centrivit Ginseng là gì? Centrivit Ginseng là sản phẩm bảo vệ sức khỏe được sản xuất bởi thương hiệu Imexpharm, nổi tiếng với các sản phẩm chất lượng cao. Viên uống này bổ sung các vitamin thiết yếu, hỗ trợ cải thiện tình trạng suy nhược, thiếu máu, biếng ăn, và mất ngủ. Đặc biệt, sản phẩm còn giúp tăng cường sức đề kháng, phù hợp với phụ nữ mang thai, trẻ em trong giai đoạn phát triển, và những người thường xuyên căng thẳng. Với thành phần từ thiên nhiên, Centrivit Ginseng là giải pháp hiệu quả để bảo vệ và cải thiện sức khỏe mỗi ngày. Centrivit Ginseng: Viên uống bổ sung vitamin, tăng cường sức khỏe hiệu quả Thành phần Thành phần chính của Centrivit Ginseng Mỗi viên Centrivit Ginseng chứa: Thành phần Hàm lượng Vitamin A 4000 IU Vitamin D 400 IU Vitamin E 15 mg Vitamin C 75 mg Vitamin B1 2 mg Vitamin B2 2 mg Vitamin B6 2 mg Vitamin B5 10 mg Vitamin PP 20 mg Vitamin B12 5 mcg Acid folic 100 mcg Công dụng Centrivit Ginseng có tác dụng gì ? Bổ sung vitamin và khoáng chất thiết yếu, giúp ', '8931583911077');
INSERT IGNORE INTO products (sku, name, category_id, active_ingredient, registration_number, manufacturer, requires_prescription, base_unit, cost_price, retail_price, image_url, gallery, description, barcode) VALUES ('TS-80723932', 'Lưỡi Dao Phẩu Thuật Doctor số 11 (100 cái)', 210, NULL, NULL, 'Doctor', 0, 'Hộp', 126000, 180000, 'https://trungsoncare.com/images/detailed/28/luoi-dao-phau-thuat-doctor-so-11-100-cai.png', NULL, 'Lưỡi Dao Phẩu Thuật Doctor số 11 là loại lưỡi dao mổ được sử dụng phổ biến nhất, dùng để tạo ra các vết rạch dài trong phòng mổ. Sản phẩm được đóng gói theo quy cách 100 lưỡi dao/ hộp, với từng lưỡi dao phẫu thuật đều. Mô tả sản phẩm Lưỡi Dao Phẩu Thuật Doctor số 11 đạt tiêu chuẩn y tế cụ thể: Dao được chế tạo bằng thép hợp kim mạ niken với độ dày đạt tiêu chuẩn bám chắc vào thân giúp chống ăn mòn, gỉ sét. Bề mặt lưỡi dao sáng bóng, bề mặt dao không được có vết lõm, vết nứt, vết xước, ba via và rỗ. Độ nhám và cứng đạt tiêu chuẩn. Lưỡi dao y tế 11 bán đảm bảo độ sắc, không có vết nứt, vết răng cưa và sứt mẻ giúp các bác sỹ có thể thực hiện những đường môt chuẩn xác. Sản phẩm được đóng gói vô trùng trước khi sử dụng chống nhiễm khuẩn cho bệnh nhân. Công dụng Lưỡi Dao Phẩu Thuật Doctor số 11 sử dụng trong phòng mổ, phòng khám bệnh viện để thực hiện đường rạch dài hay ngắn, nông hay sâu. Cách dùng Dùng kéo cắt từng mối chỉ một cách nhẹ nhàng, tránh làm tổn thương mô sẹo và giảm bớt cảm giá', '8932877559192');
INSERT IGNORE INTO products (sku, name, category_id, active_ingredient, registration_number, manufacturer, requires_prescription, base_unit, cost_price, retail_price, image_url, gallery, description, barcode) VALUES ('TS-36570285', 'Băng keo cá nhân neon Nexcare Neon Plastic (gói 9 miếng)', 199, 'Keo: Acrylate dùng cho y tế, Băng: Màng PE, Gạc: Màng PE không dệt, không dính lên vết thương', NULL, '3M (Mỹ)', 0, 'Gói', 11200, 16000, 'https://trungsoncare.com/images/detailed/11/1_d6od-mr.png', '["https://trungsoncare.com/images/detailed/11/1_d6od-mr.png","https://trungsoncare.com/images/detailed/11/2_umm4-6v.png","https://trungsoncare.com/images/detailed/11/3_scs3-c0.png","https://trungsoncare.com/images/detailed/11/4_z8qg-vv.png"]', 'Băng keo cá nhân neon Nexcare Neon Plastic Mô tả sản phẩm -Ngày nay trong tủ thuốc gia đình của mỗi nhà cần nên có các loại thiết bị, dụng cụ y tế cần thiết như nhiệt kế, máy đo huyết áp, máy đo đường huyết, bông gòn, băng gạc, băng cá nhân,... để có thể sử dụng ngay khi cần dùng đến. Thành phần Thông tin thành phần:-Băng: Màng PE-Gạc: Màng PE không dệt, không dính lên vết thương-Keo: Acrylate dùng cho y tế. Công dụng -Băng cá nhân Nexcare Neon Plastic giúp băng các vết thương, vết xước, bảo vệ vết thương thông thoáng.-Mềm mại, thoáng khí giúp cho mồ hôi và độ ẩm thoát hơi.-Thông thoáng khí, bảo vệ các vết thương, không thấm nước. Cách dùng - Lau và làm khô vết thương, dán trực tiếp lên vùng bị thương. Tác dụng phụ -Chưa có thông tin về tác dụng phụ của sản phẩm. Lưu ý -Không sử dụng khi vết thường còn ướt Bảo quản -Nơi khô ráo, nhiệt độ phòng. Tránh ánh sáng và nơi có nguồn nhiệt cao.-Để xa tầm tay trẻ em.', '8931672038049');
INSERT IGNORE INTO products (sku, name, category_id, active_ingredient, registration_number, manufacturer, requires_prescription, base_unit, cost_price, retail_price, image_url, gallery, description, barcode) VALUES ('TS-14207427', 'Let''s C Premium - Viên uống bổ sung Vitamin C, Kẽm và Vitamin D - Hộp 60 viên', 71, NULL, NULL, 'KOLMAR', 0, '01', 154000, 220000, 'https://trungsoncare.com/images/detailed/37/thuc-pham-bao-ve-suc-khoe-condition-lets-c-premium-hop-60-vien__1_.png', '["https://trungsoncare.com/images/detailed/37/thuc-pham-bao-ve-suc-khoe-condition-lets-c-premium-hop-60-vien__1_.png","https://trungsoncare.com/images/detailed/29/thuc-pham-bao-ve-suc-khoe-condition-lets-c-premium-hop-60-vien-3.jpg","https://trungsoncare.com/images/detailed/29/thuc-pham-bao-ve-suc-khoe-condition-lets-c-premium-hop-60-vien-2.jpg","https://trungsoncare.com/images/detailed/37/thuc-pham-bao-ve-suc-khoe-condition-lets-c-premium-hop-60-vien__1_.jpg"]', 'Thành phần Thành phần thực phẩm bảo vệ sức khoẻ Condition Let''s C Premium Trong 2 viên nén có chứa: Thành phần Hàm lượng Vitamin C (Ascorbic acid) 1000mg Kẽm (Kẽm oxide) 8.5 mg Vitamin D3 (Cholecalciferol) 400 IU Thành phần khác: Chất độn (Cellulose, Hydroxypropyl methylcellulose) Chất chống đông vón (Magnesium stearate, Silicon dioxid, Canxi cacbonat hỗn hợp) Chất nhũ hóa (Hydroxypropyl cellulose, Este glyxerin của axit béo) Chất kết dính (Stearate acid) Chất tạo màu tự nhiên (Chiết xuất trái dành dành (Gardenia Yellow)) Công dụng Công dụng thực phẩm bảo vệ sức khoẻ Condition Let''s C Premium Hỗ trợ bổ sung Vitamin C, Kẽm và Vitamin D, giúp hỗ trợ tăng sức đề kháng cho cơ thể, cần thiết cho quá trình hấp thụ sắt và canxi . Hỗ trợ chống oxy hóa và giảm nguy cơ loãng xương. Thực phẩm bảo vệ sức khoẻ Condition Let''s C Premium - Hộp 60 viên Cách dùng Hướng dẫn cách dùng Sử dụng 2 viên/ngày sau bữa ăn. Đối tượng sử dụng Thực phẩm bảo vệ sức khoẻ Condition Let''s C Premium thích hợp sử dụng c', '8932187093664');
INSERT IGNORE INTO products (sku, name, category_id, active_ingredient, registration_number, manufacturer, requires_prescription, base_unit, cost_price, retail_price, image_url, gallery, description, barcode) VALUES ('TS-41614622', 'Feromin – Hỗ trợ giảm thiếu máu, bổ sung sắt và acid folic (20 ống)', 69, 'Fe (III) hydroxyd polymaltose; Acid Folic; FOS (Fructooligosaccharide); Sorbitol; Vitamin B12; Vitamin B1; Thymomodulin', NULL, 'Navifa', 0, 'Hộp', 269500, 385000, 'https://trungsoncare.com/images/detailed/35/Feromin.jpg', NULL, 'Dung dịch Feromin là gì? Feromin là thực phẩm bổ sung sắt dạng dung dịch uống, giúp hỗ trợ giảm tình trạng thiếu máu do thiếu sắt, bổ sung acid folic và vitamin B12 cần thiết cho cơ thể. Sản phẩm đặc biệt phù hợp với phụ nữ mang thai, trẻ em xanh xao, người thiếu máu do chế độ ăn uống thiếu hụt vi chất dinh dưỡng. Với công thức chứa Fe (III) hydroxyd polymaltose giúp dễ hấp thu, kết hợp cùng acid folic, vitamin B12 và thymomodulin, Feromin giúp tăng cường sức khỏe, nâng cao sức đề kháng cho người sử dụng. Thành phần chính Thành phần Hàm lượng Fe (III) hydroxyd polymaltose 100 mg Acid Folic 400 mcg Vitamin B12 1 mcg Vitamin B1 1mg Thymomodulin 20 mg FOS 50 mg Sorbitol 100 mg Fe (III) hydroxyd polymaltose (100 mg): Hỗ trợ bổ sung sắt, giúp cải thiện tình trạng thiếu máu. Acid Folic (400 mcg): Tham gia vào quá trình tạo hồng cầu, giúp ngăn ngừa thiếu máu. Vitamin B12 (1 mcg): Quan trọng trong quá trình sản xuất tế bào máu và hỗ trợ chức năng thần kinh. Vitamin B1 (1 mg): Giúp chuyển hóa n', '8934024749115');
INSERT IGNORE INTO products (sku, name, category_id, active_ingredient, registration_number, manufacturer, requires_prescription, base_unit, cost_price, retail_price, image_url, gallery, description, barcode) VALUES ('TS-29372322', 'Eumovate Cream 0.05% điều trị các tình trạng viêm da, ngứa và dị ứng, giúp giảm triệu chứng như đỏ, sưng, và kích ứng da (Tuýp 5g)', 128, 'Clobetasone butyrate 0.05%kl/kl.', NULL, 'GSK ETC', 0, 'Tuýp', 17500, 25000, 'https://trungsoncare.com/images/detailed/31/eumovate-cream-0-05-dieu-tri-cac-tinh-trang-viem-da-ngua-va-di-ung-giup-giam-trieu-chung-nhu-do-sung-va-kich-ung-da-tuyp-5g.png', '["https://trungsoncare.com/images/detailed/31/eumovate-cream-0-05-dieu-tri-cac-tinh-trang-viem-da-ngua-va-di-ung-giup-giam-trieu-chung-nhu-do-sung-va-kich-ung-da-tuyp-5g.png","https://trungsoncare.com/images/detailed/31/eumovate-cream-0-05-dieu-tri-cac-tinh-trang-viem-da-ngua-va-di-ung-giup-giam-trieu-chung-nhu-do-sung-va-kich-ung-da-tuyp-5g-02.png","https://trungsoncare.com/images/detailed/31/eumovate-cream-0-05-dieu-tri-cac-tinh-trang-viem-da-ngua-va-di-ung-giup-giam-trieu-chung-nhu-do-sung-va-kich-ung-da-tuyp-5g-03.png","https://trungsoncare.com/images/detailed/31/eumovate-cream-0-05-dieu-tri-cac-tinh-trang-viem-da-ngua-va-di-ung-giup-giam-trieu-chung-nhu-do-sung-va-kich-ung-da-tuyp-5g-04.png"]', 'Mô tả sản phẩm Eumovate Cream 0.05% kl/kl là một loại kem bôi ngoài da chứa hoạt chất clobetasone butyrate, thuộc nhóm corticosteroid nhẹ. Sản phẩm này được sử dụng để điều trị các tình trạng viêm da, ngứa và dị ứng, giúp giảm triệu chứng như đỏ, sưng, và kích ứng da. Thành phần Thành phần Hàm lượng Hoạt chất: Clobetasone butyrate 0.05%kl/kl. Tá dược: Glycerol, Glycerol monostearate, Cetostearyl alcohol, Beeswax substitute 6621, Arlacel 165, Dimeticone 20, Chlorocresol, Sodium citrate, Citric acid monohydrate, Nước tinh khiết. Công dụng EUMOVATE cream là corticosteroid dùng tại chỗ có hiệu lực trung bình được chỉ định cho người lớn, người già, trẻ em và nhũ nhi nhằm làm giảm các triệu chứng viêm và ngứa của các bệnh da đáp ứng với steroid.Các bệnh này bao gồm: Viêm da cơ địa (chàm). Viêm da tiếp xúc dị ứng hoặc kích ứng. Viêm da tiết bã. Hăm da do tã lót. Viêm da do tiếp xúc với ánh sáng. Viêm tai ngoài. Sẩn cục ngứa. Các phản ứng do côn trùng đốt. EUMOVATE có thể dùng để điều trị duy ', '8933179361050');
INSERT IGNORE INTO products (sku, name, category_id, active_ingredient, registration_number, manufacturer, requires_prescription, base_unit, cost_price, retail_price, image_url, gallery, description, barcode) VALUES ('TS-94569654', 'Dung dịch vệ sinh phụ nữ Quý Phi Vip Sao Thái Dương chống ngứa, chống viêm, khử mùi hôi (120ml)', 179, 'Aqua, Sodium lauryl ether sulfat, Piper betle Extract, Coco amido betain, PEG - 75 - Lanolin, Palm kernel oil Diethanolamid, Glycerin, Menthol, Metha avenis oil, Citric Acid, Dimethylol - Dimethyl hydantoin, Sodium chlorid, Sodium lourid, Ethylen diamin T', NULL, 'Sao Thái Dương (Việt Nam)', 0, 'Chai', 42000, 60000, 'https://trungsoncare.com/images/detailed/27/dung-dich-ve-sinh-phu-nu-quy-phi-vip-sao-thai-duong-chong-ngua-chong-viem-khu-mui-hoi-120ml___1_.png', '["https://trungsoncare.com/images/detailed/27/dung-dich-ve-sinh-phu-nu-quy-phi-vip-sao-thai-duong-chong-ngua-chong-viem-khu-mui-hoi-120ml___1_.png","https://trungsoncare.com/images/detailed/27/dung-dich-ve-sinh-phu-nu-quy-phi-vip-sao-thai-duong-chong-ngua-chong-viem-khu-mui-hoi-120ml___2_.png","https://trungsoncare.com/images/detailed/27/dung-dich-ve-sinh-phu-nu-quy-phi-vip-sao-thai-duong-chong-ngua-chong-viem-khu-mui-hoi-120ml___3_.png"]', 'Dung dịch vệ sinh phụ nữ Quý Phi Vip Sao Thái Dương rửa vệ sinh hằng ngày, trước và sau khi sinh hoạt tình dục. Chống ngứa, chống viêm, khử mùi hôi. Mô tả sản phẩm Dung Dịch Vệ Sinh Phụ Nữ Quý Phi Vip Sao Thái Dương 120ml với tinh chất trầu không và các thảo dược, vệ sinh phụ nữ Quí phi VIP giúp làm sạch nhẹ nhàng, khử khuẩn và cân bằn pH âm đạo, bảo vệ sự toàn vẹn của hệ vi sinh vật có lợi trong âm đạo mà rất an toàn. Hơn nữa, mùi hương tinh tế quí phái của Quí Phi VIP giúp phái đẹp tự tin và thăng hoa trong cuộc sống. Thành phần Dung dịch vệ sinh phụ nữ Quý Phi Vip Sao Thái Dương có chứa các thành phần: Thành phần Hàm lượng Aqua, Sodium lauryl ether sulfat, Piper betle Extract, Coco amido betain, PEG - 75 - Lanolin, Palm kernel oil Diethanolamid, Glycerin, Menthol, Metha avenis oil, Citric Acid, Dimethylol - Dimethyl hydantoin, Sodium chlorid, Sodium lourid, Ethylen diamin Tetraacetic Acid, Perfume. Công dụng Dung dịch vệ sinh phụ nữ Quý Phi Vip Sao Thái Dương có công dụng: Vệ sinh v', '8931148473959');
INSERT IGNORE INTO products (sku, name, category_id, active_ingredient, registration_number, manufacturer, requires_prescription, base_unit, cost_price, retail_price, image_url, gallery, description, barcode) VALUES ('TS-30284617', 'Túi chườm Fashy Germany hình tráI tim đỏ trong suốt', 204, NULL, NULL, 'FASHY', 0, 'Cái', 219800, 314000, 'https://trungsoncare.com/images/detailed/16/1_3mz8-6o.png', NULL, 'TúI Chườm Fashy Germany HìNh TráI Tim Đỏ Trong Suốt Mô tả sản phẩm - Túi chườm Fashy hình trái tim được thiết kế kiểu dáng thời trang, hình trái tim bắt mắt. - Vỏ bọc sản phẩm được làm từ 80% chất liệu cotton & 20% chất liệu polyester êm dịu cho làn da của bạn. - Có nắp đậy túi chườm thiết kế rãnh an toàn chống rò rỉĐặc điểm TúI ChườM Fashy Germany HìNh TráI Tim Đỏ Trong Suốt- Túi chườm dung tích lớn 0.7 lít được đúc nguyên khối an toàn, sản phẩm không mùi và khó phai màu. Phần bình được làm từ nhựa PVC không mùi, có thể tái chế được. Sản phẩm đúc thành một khối và không có đường nối nên đảm bảo tính an toàn cao. Phần vỏ bọc được làm từ chất liệu 80% cotton và 20% polyester rất êm dịu với làn da của bạn. Sản phẩm có vỏ bọc có thể tháo và vệ sinh để giặt sạch dễ dàng. Nắp đậy túi chườm thiết kế có rãnh an toàn chống rò rỉ. Trang bị khung để bỏ hình bên ngoài, tăng thêm tính thẩm mỹ cho túi chườm. Túi chườm Fashy có thể chịu được nhiệt độ lớn từ -20 độ C đến 90 độ C.Thành phần cu', '8938860475315');
INSERT IGNORE INTO products (sku, name, category_id, active_ingredient, registration_number, manufacturer, requires_prescription, base_unit, cost_price, retail_price, image_url, gallery, description, barcode) VALUES ('TS-13419384', 'Thực phẩm bảo vệ sức khỏe: Spring Leaf Omega-3 1000mg (hộp 200 viên )', 69, 'Cho 1 viên: Dầu cá tự nhiên 1000mg (Omega 3 300mg, DHA 120mg, EPA 180mg), phụ liệu: dầu đậu nành, D- Alpha - Tocopherol', NULL, 'Spring Leaf', 0, 'Lọ', 88900, 127000, 'https://trungsoncare.com/images/detailed/28/thuc-pham-bao-ve-suc-khoe-spring-leaf-omega-3-1000mg-hop-200-vien.png', NULL, 'Thực phẩm bảo vệ sức khỏe: Spring Leaf Omega-3 1000mg bổ sung dưỡng chất giúp bổ não. Hỗ trợ cải thiện sức khỏe Mô tả sản phẩm Thành phần của thực phẩm bảo vệ sức khỏe: Spring Leaf Omega-3 1000mg Cho 1 viên: Thành phần Hàm lượng Dầu cá tự nhiên (Omega 3 300mg, DHA 120mg, EPA 180mg), phụ liệu: dầu đậu nành, D- Alpha - Tocopherol 1000mg Công dụng Công dụng của thực phẩm bảo vệ sức khỏe: Spring Leaf Omega-3 1000mg - Bổ sung dưỡng chất giúp bổ não. Hỗ trợ cải thiện sức khỏe Thực phẩm bảo vệ sức khỏe: Spring Leaf Omega-3 1000mg bổ sung dưỡng chất giúp bổ não. Hỗ trợ cải thiện sức khỏe Cách dùng - Uống 3 viên/ngày chia 3 lần sau ăn hoặc theo liều chỉ định của chuyên gia y tế Đối tượng sử dụng -Dùng cho người lớn Bảo quản - Nơi khô ráo thoáng mát, dưới 30 "C ⚠️ Lưu ý Không dùng cho người mẫn cảm với bất kể thành phân nào của sản phẩm Thực phẩm bảo vệ sức khỏe: Spring Leaf Omega-3 1000mg không phải là thuốc và không có tác dụng thay thế thuốc chữa bệnh.', '8932931324772');
